import React, { useEffect, useState } from "react";
import { useLocation, useParams } from "react-router-dom";
import {
  Button,
  CheckboxGroup,
  Checkbox,
  Radio,
  RadioGroup,
  Select,
  SelectItem,
} from "@heroui/react";
import useApi from "../../../hooks/useApi";
import transportApi from "../../../api/transport/transportApi";
import Seat from "../../../components/transport/Seat";
import { toast, ToastContainer } from "react-toastify";
import makeAnimated from "react-select/animated";
import TextInput from "../../../components/TextInput";
import JambopayAuthorizationModal from "./JambopayAuthorizationModal";

const identifierTypes = [
  { label: "National ID", value: "NationalId" },
  { label: "Passport", value: "Passport" },
];

function TripDetails() {
  const animatedComponent = makeAnimated();
  const location = useLocation();
  const { id } = useParams();
  const [tripID, settripID] = useState(null);
  const [selectedSeats, setselectedSeats] = useState([]);
  const [trip, settrip] = useState();
  const transportActionsApi = useApi(transportApi.transportAction);
  const [destinations, setDestinations] = useState([]);
  const [allPassengers, setAllPassengers] = useState([]);
  const [openForm, setopenForm] = useState(false);
  const [selectedCharges, setselectedCharges] = useState([]);
  const [selectedDestination, setselectedDestination] = useState();
  const [ticketCharges, setticketCharges] = useState([]);
  const [paymentMethods, setpaymentMethods] = useState([]);
  const [selectedPaymentMethod, setselectedPaymentMethod] = useState();
  const [selectedSeatForm, setselectedSeatForm] = useState(false);
  const [mobileMoneyPhoneRequired, setmobileMoneyPhoneRequired] =
    useState(false);

  const [jambopayWalletPhoneRequired, setjambopayWalletPhoneRequired] =
    useState(false);
  const [mobileMoneyPhone, setmobileMoneyPhone] = useState("");
  const [jambopayWalletPhone, setjambopayWalletPhone] = useState("");
  const [reference, setReference] = useState();
  const [authorizationModalOpen, setauthorizationModalOpen] = useState(false);
  const [showJPAuthDialog, setshowJPAuthDialog] = useState(false);

  const [errors, setErrors] = useState([]);

  const getTripDetails = async (id) => {
    await transportActionsApi.request({
      action: "GetTripDetails",
      trip: id,
    });
  };

  const getPaymentMethods = async () => {
    await transportActionsApi.request({
      action: "GetPaymentMethods",
    });
  };

  useEffect(() => {
    getPaymentMethods();
  }, []);

  useEffect(() => {
    if (errors && errors.length) {
      errors.map((x) => {
        toast.error(x);
      });
    }
  }, [errors]);

  useEffect(() => {
    if (transportActionsApi.data && transportActionsApi.data.length) {
      setpaymentMethods(transportActionsApi.data);
    }

    if (
      transportActionsApi.data &&
      transportActionsApi.data.response_code === 0
    ) {
      toast.success(transportActionsApi.data.response_message);
    }

    if (
      transportActionsApi.data &&
      transportActionsApi.data.response_code === 1
    ) {
      toast.error(transportActionsApi.data.response_message);
    }

    if (transportActionsApi.data && transportActionsApi.data.errors) {
      setErrors(transportActionsApi.data.errors);
    }

    console.log("transportActionsApi.data", transportActionsApi.data);
  }, [transportActionsApi.data]);

  useEffect(() => {
    if (id) {
      settripID(id);
    }
  }, [id]);

  useEffect(() => {
    console.log("allPassengers", allPassengers);
  }, [allPassengers]);

  useEffect(() => {
    console.log("selectedCharges", selectedCharges);
  }, [selectedCharges]);
  useEffect(() => {
    if (tripID) {
      getTripDetails(tripID);
    }
    console.log("idee", tripID);
  }, [tripID]);

  useEffect(() => {
    if (transportActionsApi.data && transportActionsApi.data.trip) {
      settrip(transportActionsApi.data.trip);
    }

    console.log("transportActionsApi.data", transportActionsApi.data);
  }, [transportActionsApi.data]);

  useEffect(() => {
    if (
      trip &&
      trip.route_details.destinations &&
      trip.route_details.destinations.length
    ) {
      setDestinations(
        trip.route_details.destinations.map((i) => ({
          label: i.title,
          value: i.id,
        }))
      );
    }
  }, [trip]);

  const handleSelectAction = (seat, isSeatSold) => {
    console.log(seat.toString(), isSeatSold);
    if (isSeatSold) {
      toast.error("Seat is not availabe");
    } else {
      if (allPassengers && allPassengers.length) {
        const isIn = allPassengers.find((x) => x.seat === seat);
        if (isIn) {
          setAllPassengers(
            allPassengers.filter((pass) => pass.seat !== isIn.seat)
          );
          const seats = selectedSeats.filter(
            (selelectedSeat) => selelectedSeat !== isIn.seat
          );
          setselectedSeats(seats);
          return;
        }
      }

      const stump = {
        trip: trip.id,
        route: trip.route,
        seat: seat,
        first_name: "",
        last_name: "",
        destination: "",
        identifier_type: "",
        identifier_number: "",
        vehicle: trip.vehicle,
        passenger_phone: "",
        origin: "WEB",
      };
      setAllPassengers((prevState) => [...prevState, stump]);
      setselectedSeats((prevState) => [...prevState, stump.seat]);
    }
  };

  useEffect(() => {
    console.log("selected seats", selectedSeats);
  }, [selectedSeats]);
  useEffect(() => {
    console.log("selectedDestination", selectedDestination);
    setselectedCharges(
      selectedDestination && selectedDestination.charges
        ? selectedDestination.charges
        : []
    );
  }, [selectedDestination]);

  useEffect(() => {
    console.log("destinations", destinations);
  }, [destinations]);
  useEffect(() => {
    console.log("selectedCharges", selectedCharges);
  }, [selectedCharges]);
  useEffect(() => {
    console.log("ticketCharges", ticketCharges);
  }, [ticketCharges]);
  useEffect(() => {
    console.log("mobileMoneyPhone", mobileMoneyPhone);
  }, [mobileMoneyPhone]);

  const createTicketsApi = useApi(transportApi.transportAction);
  const createBatchedTickets = async (data) => {
    await createTicketsApi.request(data);
  };

  useEffect(() => {
    if (createTicketsApi.data && createTicketsApi.data.response_code === 0) {
      toast.success(createTicketsApi.data.response_message);
      setAllPassengers(null);
      getTripDetails(tripID);
      console.log("result of create batch tickets", createTicketsApi.data);
      if (createTicketsApi.data.reference !== null) {
        setReference(createTicketsApi.data.reference);
        setauthorizationModalOpen(true);
      }
    }

    if (createTicketsApi.data && createTicketsApi.data.response_code === 1) {
      toast.error(createTicketsApi.data.response_message);
    }

    if (createTicketsApi.data && createTicketsApi.data.errors) {
      setErrors(createTicketsApi.data.errors);
    }

    console.log("createTicketsApi.data", createTicketsApi.data);
  }, [createTicketsApi.data]);

  const handleSubmit = (event) => {
    event.preventDefault();
    console.log("eee", event);
    console.log("allPassengers", allPassengers);
    const data = {
      action: "CreateBatchedTickets",
      mobile_money_phone: mobileMoneyPhone,
      jambopay_wallet_phone: jambopayWalletPhone,
      payment_method: selectedPaymentMethod.id,
      tickets: allPassengers,
    };

    console.log("data", data);

    createBatchedTickets(data);
  };

  // Function to update the value of an input field
  const handleInputChange = (index, event) => {
    console.log("Event", event);
    console.log("Index", index);

    const values = [...allPassengers];
    const updatedValue = event.target.name;
    values[index][updatedValue] = event.target.value;

    setAllPassengers(values);

    if (updatedValue === "destination") {
      toast.success("Destinations have changed");
      setselectedDestination(
        trip.route_details.destinations.find((x) => x.id === event.target.value)
      );
    }
  };

  const handleSelectPaymentMethod = (e, method) => {
    setselectedPaymentMethod(e.target.value);
    if (method.title === "MOBILE MONEY") {
      setmobileMoneyPhoneRequired(true);
    } else {
      setmobileMoneyPhoneRequired(false);
    }

    if (method.title === "JAMBOPAY WALLET") {
      setjambopayWalletPhoneRequired(true);
      setshowJPAuthDialog(true);
    } else {
      setjambopayWalletPhoneRequired(false);
    }
    setselectedPaymentMethod(method);
  };

  return (
    <div className="grid  grid-cols-2 gap-x-6 bg-gray-100">
      <div>
        <ToastContainer theme="colored" position="bottom-center" />
        {trip ? (
          <div className="items-center justify-center flex-col flex mt-12 shadow-lg p-3">
            <p className="font-bold text-2xl">
              VEHICLE: {trip.vehicle_registration}
            </p>
            <p>ROUTE: {trip.route_title}</p>
            <div className="grid grid-cols-3  space-x-3">
              {trip &&
                trip.seats_configuration &&
                trip.seats_configuration.row1.map((seat) => (
                  <Seat
                    handleSelectAction={handleSelectAction}
                    selectedSeats={selectedSeats}
                    trip={trip}
                    seat={seat}
                  />
                ))}
            </div>

            <div className="grid grid-cols-3  space-x-3">
              {trip &&
                trip.seats_configuration &&
                trip.seats_configuration.row2.map((seat) => (
                  <Seat
                    handleSelectAction={handleSelectAction}
                    selectedSeats={selectedSeats}
                    trip={trip}
                    seat={seat}
                  />
                ))}
            </div>
            <div className="grid grid-cols-3  space-x-3">
              {trip &&
                trip.seats_configuration &&
                trip.seats_configuration.row3.map((seat) => (
                  <Seat
                    handleSelectAction={handleSelectAction}
                    selectedSeats={selectedSeats}
                    trip={trip}
                    seat={seat}
                  />
                ))}
            </div>
            <div className="grid grid-cols-3  space-x-3">
              {trip &&
                trip.seats_configuration &&
                trip.seats_configuration.row4.map((seat) => (
                  <Seat
                    handleSelectAction={handleSelectAction}
                    selectedSeats={selectedSeats}
                    trip={trip}
                    seat={seat}
                  />
                ))}
            </div>
            <div className="grid grid-cols-3  space-x-3">
              {trip &&
                trip.seats_configuration &&
                trip.seats_configuration.row5.map((seat) => (
                  <Seat
                    handleSelectAction={handleSelectAction}
                    selectedSeats={selectedSeats}
                    trip={trip}
                    seat={seat}
                  />
                ))}
            </div>

            <div></div>
          </div>
        ) : (
          <div>
            <p>Trip details not found</p>
          </div>
        )}
      </div>

      <div className="items-center justify-center flex-col flex  shadow-lg p-3 shadow-gray-400 ">
        {allPassengers && allPassengers.length ? (
          <div className="items-center justify-center flex-col flex ">
            <p className="font-bold text-2xl underline ">
              Selected seats: {selectedSeats.join(", ")}
            </p>

            <form onSubmit={handleSubmit}>
              <div className="grid grid-cols-1 md:grid-cols-2 space-x-2">
                {allPassengers.map((field, index) => (
                  <div className="input-container shadow-md" key={index}>
                    <p className="text-xl font-bold mt-4 text-center">
                      Seat No. {field.seat}
                    </p>

                    <div className="grid grid-cols-2 w-full">
                      <TextInput
                        type="text"
                        name="first_name"
                        placeholder="Enter first name"
                        value={field.first_name}
                        onChange={(event) => handleInputChange(index, event)}
                      />

                      <TextInput
                        type="text"
                        name="last_name"
                        placeholder="Enter last name"
                        value={field.last_name}
                        onChange={(event) => handleInputChange(index, event)}
                      />

                      <TextInput
                        type="text"
                        name="passenger_phone"
                        placeholder="Enter passenger phone"
                        value={field.phone}
                        onChange={(event) => handleInputChange(index, event)}
                      />

                      <Select
                        variant="bordered"
                        label="Select identifier type"
                        className="bg-white mt-2"
                        name="identifier_type"
                        value={field.identifier_type}
                        onChange={(event) => handleInputChange(index, event)}
                      >
                        {identifierTypes.map((option) => (
                          <SelectItem key={option.value} value={option.value}>
                            {option.label}
                          </SelectItem>
                        ))}
                      </Select>

                      <TextInput
                        type="text"
                        name="identifier_number"
                        placeholder="Enter identifier number"
                        value={field.identifier_number}
                        onChange={(event) => handleInputChange(index, event)}
                      />

                      <Select
                        variant="bordered"
                        label="Select destination"
                        className="bg-white mt-4"
                        name="destination"
                        value={field.destination}
                        onChange={(event) => handleInputChange(index, event)}
                      >
                        {destinations.map((option) => (
                          <SelectItem key={option.value} value={option.value}>
                            {option.label}
                          </SelectItem>
                        ))}
                      </Select>
                    </div>
                  </div>
                ))}
              </div>
              {allPassengers.length && paymentMethods.length ? (
                <div className="text-center">
                  <RadioGroup
                    className="bg-white p-4 max-w-md self-center mt-4"
                    label="Select payment method"
                  >
                    {paymentMethods.map((method) => (
                      <Radio
                        onChange={(e) => handleSelectPaymentMethod(e, method)}
                        value={method.id}
                      >
                        {method.title}
                      </Radio>
                    ))}
                  </RadioGroup>

                  {mobileMoneyPhoneRequired && (
                    <TextInput
                      type="text"
                      name="mobile_money_phone"
                      placeholder="Enter mobile money number for payment"
                      value={mobileMoneyPhone}
                      onChange={(event) =>
                        setmobileMoneyPhone(event.target.value)
                      }
                    />
                  )}

                  {jambopayWalletPhoneRequired && (
                    <TextInput
                      type="text"
                      name="jambopay_wallet_phone"
                      placeholder="Enter Jambopay Wallet number"
                      value={jambopayWalletPhone}
                      onChange={(event) =>
                        setjambopayWalletPhone(event.target.value)
                      }
                    />
                  )}
                  <Button
                    type="submit"
                    color="primary"
                    className="max-w-md w-56 mt-4"
                  >
                    Save
                  </Button>
                </div>
              ) : (
                <div></div>
              )}
            </form>
          </div>
        ) : (
          <p>No seats are selected</p>
        )}

        {reference && showJPAuthDialog && (
          <JambopayAuthorizationModal
            authorizationModalOpen={authorizationModalOpen}
            setauthorizationModalOpen={setauthorizationModalOpen}
            reference={reference}
          />
        )}
      </div>
    </div>
  );
}

export default TripDetails;
